import { v4 as uuidv4 } from "uuid";
import type { EventType, SimEvent } from "@/domain/types";
import { store } from "@/store/redis.store";

interface AppendEventOptions {
  material?: string
  metadata?: Record<string, unknown>
  orderId?: string
  quantity?: number
  runId: string
  scheduledEquipmentId?: string
  simulationTime?: string
  stockAfter?: number
  type: EventType
}

/**
 * Appends a simulation event to the store and returns the created event.
 * @param options - Event creation options including type, runId, and optional metadata.
 * @returns The created SimEvent.
 */
export async function appendEvent(options: AppendEventOptions): Promise<SimEvent> {
  const event: SimEvent = {
    eventId: uuidv4(),
    material: options.material,
    metadata: options.metadata,
    orderId: options.orderId,
    quantity: options.quantity,
    realTime: new Date().toISOString(),
    runId: options.runId,
    scheduledEquipmentId: options.scheduledEquipmentId,
    simulationTime: options.simulationTime ?? new Date().toISOString(),
    stockAfter: options.stockAfter,
    type: options.type,
  };
  await store.appendEvent(event);
  return event;
}

import { getRandomValues } from "node:crypto";
import { appendEvent } from "./event-log.js";
import { RequestState, RunStatus, EventType } from "@/domain/types";
import { store } from "@/store/redis.store";

const TICK_INTERVAL_MS = 5000;

/**
 * @returns A cryptographically secure random float in [0, 1).
 */
function cryptoRandom(): number {
  const buf = new Uint32Array(1);
  getRandomValues(buf);
  return buf[0] / (0xFF_FF_FF_FF + 1);
}

/**
 * Applies random jitter to a base duration.
 * @param baseSeconds - Base duration in seconds before jitter is applied.
 * @param jitterPct - Maximum jitter percentage (±) to apply.
 * @returns The jittered duration in seconds.
 */
function applyJitter(baseSeconds: number, jitterPct: number): number {
  const factor = 1 + (cryptoRandom() * 2 - 1) * (jitterPct / 100);
  return baseSeconds * factor;
}

/**
 * Releases Forecast work requests whose targetReleaseAt has passed.
 * @param wrs - Work requests for the current run.
 * @param runId - ID of the simulation run.
 * @param now - Current tick timestamp.
 */
async function releaseForecasts(
  wrs: Awaited<ReturnType<typeof store.getAllWorkRequests>>,
  runId: string,
  now: Date,
): Promise<void> {
  const forecasts = wrs.filter(w => w.requestState === RequestState.Forecast && new Date(w.targetReleaseAt) <= now);
  await Promise.all(
    forecasts.map(async (wr) => {
      const updated = { ...wr, releasedAt: now.toISOString(), requestState: RequestState.Released };
      await store.setWorkRequest(updated.id, updated);
      await appendEvent({
        material: updated.material ?? undefined,
        orderId: updated.id,
        runId,
        scheduledEquipmentId: updated.scheduledEquipmentId,
        type: EventType.WORK_REQUEST_UPDATED,
      });
    }),
  );
}

/**
 * Starts the highest-priority Released work request for each idle machine.
 * @param wrs - Work requests for the current run.
 * @param runId - ID of the simulation run.
 * @param now - Current tick timestamp.
 */
async function startNextWorkRequests(
  wrs: Awaited<ReturnType<typeof store.getAllWorkRequests>>,
  runId: string,
  now: Date,
): Promise<void> {
  const machines = new Set(wrs.map(w => w.scheduledEquipmentId));
  await Promise.all(
    [...machines].map(async (equipmentId) => {
      const isRunning = wrs.some(
        w => w.scheduledEquipmentId === equipmentId && w.requestState === RequestState.Running,
      );
      if (isRunning) return;

      const next = wrs
        .filter(w => w.scheduledEquipmentId === equipmentId && w.requestState === RequestState.Released)
        .sort((a, b) => a.priority - b.priority)[0];

      if (next === undefined) return;

      // BOM not yet resolved — skip until Phase 5 SQL Server integration populates durationSeconds
      if (next.durationSeconds === undefined) return;

      const machine = await store.getMachine(equipmentId);
      const cycleTimeSeconds = next.durationSeconds / next.orderedQuantity;
      const jitterPct = machine?.cycleTimeJitterPct ?? 0;
      const firstCycleMs = applyJitter(cycleTimeSeconds, jitterPct) * 1000;

      const updated = {
        ...next,
        estimatedCompletionAt: new Date(now.getTime() + next.durationSeconds * 1000).toISOString(),
        nextCycleAt: new Date(now.getTime() + firstCycleMs).toISOString(),
        requestState: RequestState.Running,
        startedAt: now.toISOString(),
      };
      await store.setWorkRequest(updated.id, updated);
      await appendEvent({
        material: updated.material ?? undefined,
        orderId: updated.id,
        runId,
        scheduledEquipmentId: equipmentId,
        type: EventType.WORK_REQUEST_STARTED,
      });
    }),
  );
}

/**
 * Advances running work requests by one cycle tick.
 * @param wrs - Work requests for the current run.
 * @param runId - ID of the simulation run.
 * @param now - Current tick timestamp.
 */
async function tickRunningWorkRequests(
  wrs: Awaited<ReturnType<typeof store.getAllWorkRequests>>,
  runId: string,
  now: Date,
): Promise<void> {
  const dueWrs = wrs.filter(
    w => w.requestState === RequestState.Running && w.nextCycleAt !== undefined && new Date(w.nextCycleAt) <= now,
  );

  await Promise.all(
    dueWrs.map(async (wr) => {
      const machine = await store.getMachine(wr.scheduledEquipmentId);
      const reference = wr.material == null ? undefined : await store.getReference(wr.material);
      const cycleTimeSeconds = (wr.durationSeconds ?? 0) / wr.orderedQuantity;
      const jitterPct = machine?.cycleTimeJitterPct ?? 0;
      const piecesPerCycle = reference?.piecesPerCycle ?? 1;

      const newRemaining = Math.max(0, wr.remainingQuantity - piecesPerCycle);
      const stockKey = wr.material == null ? undefined : store.stockKey(runId, wr.material);
      const stock = stockKey == null ? undefined : await store.getStock(stockKey);
      const newStock = (stock?.currentStock ?? 0) + piecesPerCycle;

      if (stock != null && stockKey != null) {
        await store.setStock(stockKey, { ...stock, currentStock: newStock, lastUpdatedAt: now.toISOString() });
      }

      await appendEvent({
        material: wr.material ?? undefined,
        orderId: wr.id,
        quantity: piecesPerCycle,
        runId,
        scheduledEquipmentId: wr.scheduledEquipmentId,
        stockAfter: newStock,
        type: EventType.CYCLE_COMPLETED,
      });

      if (newRemaining <= 0) {
        const completed = {
          ...wr,
          completedAt: now.toISOString(),
          nextCycleAt: undefined,
          remainingQuantity: 0,
          requestState: RequestState.Completed,
        };
        await store.setWorkRequest(completed.id, completed);
        await appendEvent({
          material: completed.material ?? undefined,
          orderId: completed.id,
          quantity: completed.orderedQuantity,
          runId,
          scheduledEquipmentId: completed.scheduledEquipmentId,
          type: EventType.WORK_REQUEST_COMPLETED,
        });
      }
      else {
        const nextCycleMs = applyJitter(cycleTimeSeconds, jitterPct) * 1000;
        const advanced = {
          ...wr,
          nextCycleAt: new Date(now.getTime() + nextCycleMs).toISOString(),
          remainingQuantity: newRemaining,
        };
        await store.setWorkRequest(advanced.id, advanced);
      }
    }),
  );
}

/**
 * Runs a single simulation tick across all active runs.
 */
async function tick(): Promise<void> {
  const runs = await store.getAllRuns();
  const activeRuns = runs.filter(r => r.status === RunStatus.RUNNING);
  if (activeRuns.length === 0) return;

  const allWrs = await store.getAllWorkRequests();
  const now = new Date();

  await Promise.all(
    activeRuns.map(async (run) => {
      const wrs = allWrs.filter(w => w.runId === run.runId);
      await releaseForecasts(wrs, run.runId, now);
      await startNextWorkRequests(wrs, run.runId, now);
      await tickRunningWorkRequests(wrs, run.runId, now);
    }),
  );
}

/**
 * Starts the simulation engine tick loop.
 */
export function startEngine(): void {
  setInterval(() => {
    tick().catch(() => { /* Intentionally swallow tick errors */ });
  }, TICK_INTERVAL_MS);
}

import type { FastifyInstance } from "fastify";
import type { SimConfig } from "@/domain/types";
import { store } from "@/store/redis.store";

/**
 * Registers simulation config routes.
 * @param app - Fastify application instance.
 */
export async function configRoutes(app: FastifyInstance): Promise<void> {
  app.get("/api/config", async () => store.getConfig());

  app.put<{ Body: SimConfig }>("/api/config", async (request, reply) => {
    const { leadTimeSeconds } = request.body;
    if (leadTimeSeconds === undefined || leadTimeSeconds < 0) {
      return reply.code(400).send({ error: "INVALID_CONFIG", message: "leadTimeSeconds must be >= 0" });
    }
    await store.setConfig({ leadTimeSeconds });
    return store.getConfig();
  });
}

import type { FastifyInstance } from "fastify";
import { store } from "@/store/redis.store";

/**
 * Registers event query routes.
 * @param app - Fastify application instance.
 */
export function eventRoutes(app: FastifyInstance): void {
  app.get<{
    Querystring: {
      from?: string
      limit?: string
      material?: string
      offset?: string
      orderId?: string
      runId?: string
      scheduledEquipmentId?: string
      to?: string
      type?: string
    }
  }>("/api/events", async (request) => {
    const { runId, type, scheduledEquipmentId, material, orderId, from, to, limit, offset } = request.query;

    let results = await store.getEvents();
    if (runId !== undefined) results = results.filter(event => event.runId === runId);
    if (type !== undefined) results = results.filter(event => (event.type as string) === type);
    if (scheduledEquipmentId !== undefined) results = results.filter(event => event.scheduledEquipmentId === scheduledEquipmentId);
    if (material !== undefined) results = results.filter(event => event.material === material);
    if (orderId !== undefined) results = results.filter(event => event.orderId === orderId);
    if (from !== undefined) results = results.filter(event => event.simulationTime >= from);
    if (to !== undefined) results = results.filter(event => event.simulationTime <= to);

    const pageOffset = Number.parseInt(offset ?? "0", 10);
    const pageLimit = Number.parseInt(limit ?? "100", 10);
    return results.slice(pageOffset, pageOffset + pageLimit);
  });
}

