import type { FastifyInstance } from "fastify";
import { store } from "@/store/redis.store";

// Minimal OData $filter parser: supports eq, and, or on Plant, Material, SLocation.
// Grammar handled: Plant eq 'X' and (Material eq 'A' or Material eq 'B') and SLocation eq 'Y'
/**
 * Parses an OData $filter string into plant, materials, and sLocation parts.
 * @param filter - OData $filter query string to parse.
 * @returns Parsed plant, materials, and sLocation values, or undefined on parse failure.
 */
function parseFilter(filter: string): { materials?: Array<string>, plant?: string, sLocation?: string } | undefined {
  try {
    // Strip outer parentheses groups for material OR clauses, then split on top-level 'and'
    const materialOrMatch = /\(([^)]{1,500})\)/.exec(filter);
    const materialOrClause = materialOrMatch ? materialOrMatch[1] : undefined;
    const filterWithoutOr = filter.replace(/\([^)]{1,500}\)/, "TRUE");

    const andParts = filterWithoutOr.split(" and ").flatMap(p => p.split(" AND "));

    let plant: string | undefined;
    let sLocation: string | undefined;
    const materials: Array<string> = [];

    for (const part of andParts) {
      const trimmed = part.trim();
      if (trimmed !== "TRUE") {
        const eqMatch = /^(\w+)\s+eq\s+'([^']+)'/i.exec(trimmed);
        if (eqMatch) {
          const [, field, value] = eqMatch;
          if (field.toLowerCase() === "plant") plant = value;
          else if (field.toLowerCase() === "slocation") sLocation = value;
          else if (field.toLowerCase() === "material") materials.push(value);
        }
      }
    }

    // Parse material OR clause if present
    if (materialOrClause !== undefined) {
      const orParts = materialOrClause.split(" or ").flatMap(p => p.split(" OR "));
      for (const part of orParts) {
        const eqMatch = /^material\s+eq\s+'([^']+)'/i.exec(part.trim());
        if (eqMatch) materials.push(eqMatch[1]);
      }
    }

    return { materials: materials.length > 0 ? materials : undefined, plant, sLocation };
  }
  catch {
    return undefined;
  }
}

/**
 * Formats a number to 3 decimal places.
 * @param n - Number to format.
 * @returns The number formatted as a fixed 3-decimal-place string.
 */
function formatDecimal(n: number): string {
  return n.toFixed(3);
}

/**
 * Registers inventory OData routes.
 * @param app - Fastify application instance.
 */
export async function inventoryRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Querystring: { $filter?: string } }>("/api/sap/stockmovement/v1/ActualStockSet", async (request, reply) => {
    const rawFilter = request.query.$filter;
    let plant: string | undefined;
    let materials: Array<string> | undefined;
    let sLocation: string | undefined;

    if (rawFilter !== undefined) {
      const parsed = parseFilter(rawFilter);
      if (!parsed) {
        return reply.code(400).send({
          error: "INVALID_FILTER",
          message: "Unable to parse $filter expression. Supported fields: Plant, Material, SLocation.",
        });
      }
      plant = parsed.plant;
      materials = parsed.materials;
      sLocation = parsed.sLocation;
    }

    const allStocks = await store.getAllStocks();

    // Filter by material list if specified
    const filtered
      = materials && materials.length > 0 ? allStocks.filter(s => materials?.includes(s.material)) : allStocks;

    const results = await Promise.all(
      filtered.map(async (s) => {
        const reference = await store.getReference(s.material);
        // SAP OData contract: property names must match the external API schema exactly
        return {
          Actual: formatDecimal(s.currentStock),
          Material: s.material,
          Maximum: formatDecimal(reference?.stockMax ?? 0),
          Mininmum: formatDecimal(reference?.stockMin ?? 0),
          Plant: plant ?? "",
          SLocation: sLocation ?? "",
          StockBySL: "",
          __metadata: {
            id: `ActualStockSet(Plant='${plant ?? ""}',SLocation='${sLocation ?? ""}',Material='${s.material}')`,
            type: "ZPP_STOCKMVT_SRV.ActualStock",
            uri: `ActualStockSet(Plant='${plant ?? ""}',SLocation='${sLocation ?? ""}',Material='${s.material}')`,
          },
        };
      }),
    );

    return { d: { results } };
  });
}

import type { FastifyInstance } from "fastify";
import type { ConsumptionSignalEvent } from "@/domain/types";
import { store } from "@/store/redis.store";

/**
 * Registers consumption signal routes.
 * @param app - Fastify application instance.
 */
export async function signalRoutes(app: FastifyInstance): Promise<void> {
  app.get("/api/signals", async () => store.getAllSignals());

  app.get<{ Params: { signalId: string } }>("/api/signals/:signalId", async (request, reply) => {
    const signal = await store.getSignal(request.params.signalId);
    if (!signal) return reply.code(404).send({ error: "NOT_FOUND" });
    const signalEvents = await store.getSignalEvents(request.params.signalId);
    const events = signalEvents.slice(0, 20);
    return { ...signal, previewEvents: events };
  });

  app.post("/api/signals", async (request, reply) => {
    const data = request.body as {
      description: string
      events: Array<ConsumptionSignalEvent>
      signalId: string
      unit: string
    };

    if (!data.signalId || !data.events?.length) {
      return reply.code(400).send({ error: "INVALID_SIGNAL", message: "signalId and events[] are required" });
    }

    const sortedEvents = [...data.events].sort((a, b) => a.offsetSeconds - b.offsetSeconds);
    const signal = {
      description: data.description ?? "",
      eventCount: sortedEvents.length,
      signalId: data.signalId,
      unit: data.unit ?? "pcs",
    };

    await store.setSignal(signal.signalId, signal);
    await store.setSignalEvents(signal.signalId, sortedEvents);

    return reply.code(201).send(signal);
  });
}

import { RunStatus, StockUpdateMode, RequestState } from "@/domain/types";
import { store } from "@/store/redis.store";
import { buildApp, connectStore, resetStore } from "@/test/app";

beforeAll(async () => {
  await connectStore();
});
afterAll(async () => {
  await store.disconnect();
});

describe("POST /api/simulation/runs", () => {
  let app: ReturnType<typeof buildApp>;

  beforeEach(async () => {
    await resetStore();
    app = buildApp();
  });
  afterEach(() => app.close());

  it("creates a run with IDLE status and returns 201", async () => {
    const response = await app.inject({
      method: "POST",
      url: "/api/simulation/runs",
      payload: { signalLoop: false, stockUpdateMode: StockUpdateMode.PerCycle },
    });
    expect(response.statusCode).toBe(201);
    const body = response.json();
    expect(body.runId).toBeDefined();
    expect(body.status).toBe(RunStatus.IDLE);
  });

  it("initialises stock for all known references", async () => {
    await store.setReference("MAT-A", {
      description: "Test",
      initialStock: 50,
      material: "MAT-A",
      piecesPerCycle: 1,
      stockMax: 100,
      stockMin: 10,
      unit: "pcs",
    });
    const response = await app.inject({ method: "POST", url: "/api/simulation/runs", payload: {} });
    const { runId } = response.json();
    const key = store.stockKey(runId, "MAT-A");
    const stock = await store.getStock(key);
    expect(stock?.currentStock).toBe(50);
  });
});

describe("POST /api/simulation/runs/:runId/start", () => {
  let app: ReturnType<typeof buildApp>;
  let runId: string;

  beforeEach(async () => {
    await resetStore();
    app = buildApp();
    const response = await app.inject({ method: "POST", url: "/api/simulation/runs", payload: {} });
    runId = response.json().runId;
  });
  afterEach(() => app.close());

  it("transitions run to RUNNING", async () => {
    const response = await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/start` });
    expect(response.statusCode).toBe(200);
    expect(response.json().status).toBe(RunStatus.RUNNING);
  });

  it("records startedAt on first start", async () => {
    const response = await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/start` });
    expect(response.json().startedAt).toBeDefined();
  });

  it("returns 409 ALREADY_RUNNING when run is already running", async () => {
    await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/start` });
    const response = await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/start` });
    expect(response.statusCode).toBe(409);
    expect(response.json().error).toBe("ALREADY_RUNNING");
  });

  it("returns 404 for unknown runId", async () => {
    const response = await app.inject({ method: "POST", url: "/api/simulation/runs/unknown/start" });
    expect(response.statusCode).toBe(404);
  });
});

