describe("POST /api/simulation/runs/:runId/reset", () => {
  let app: ReturnType<typeof buildApp>;
  let runId: string;

  beforeEach(async () => {
    await resetStore();
    await store.setReference("MAT-A", {
      description: "Test",
      initialStock: 50,
      material: "MAT-A",
      piecesPerCycle: 1,
      stockMax: 100,
      stockMin: 10,
      unit: "pcs",
    });
    app = buildApp();
    const response = await app.inject({ method: "POST", url: "/api/simulation/runs", payload: {} });
    runId = response.json().runId;
    await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/start` });
  });
  afterEach(() => app.close());

  it("transitions run back to IDLE and clears startedAt", async () => {
    const response = await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/reset` });
    expect(response.statusCode).toBe(200);
    expect(response.json().status).toBe(RunStatus.IDLE);
    expect(response.json().startedAt).toBeUndefined();
  });

  it("restores stock to initialStock levels", async () => {
    const key = store.stockKey(runId, "MAT-A");
    const stock = await store.getStock(key);
    if (!stock) throw new Error("Expected stock to exist");
    await store.setStock(key, { ...stock, currentStock: 0 });

    await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/reset` });
    const after = await store.getStock(key);
    expect(after?.currentStock).toBe(50);
  });

  it("clears work requests belonging to this run", async () => {
    await store.setWorkRequest("wr-1", {
      createdAt: new Date().toISOString(),
      durationSeconds: 3600,
      endTime: "2026-06-01T09:00:00Z",
      id: "wr-1",
      material: "MAT-A",
      orderedQuantity: 10,
      priority: 1,
      remainingQuantity: 10,
      requestState: RequestState.Forecast,
      runId,
      scheduledEquipmentId: "WC001",
      schedulerOrderId: "SCH-1",
      startTime: "2026-06-01T08:00:00Z",
      targetReleaseAt: new Date().toISOString(),
      workMasterId: "wm-001",
      workMasterVersion: "1",
    });
    await app.inject({ method: "POST", url: `/api/simulation/runs/${runId}/reset` });
    expect(await store.hasWorkRequest("wr-1")).toBe(false);
  });

  it("returns 404 for unknown runId", async () => {
    const response = await app.inject({ method: "POST", url: "/api/simulation/runs/unknown/reset" });
    expect(response.statusCode).toBe(404);
  });
});

describe("GET /api/simulation/runs/:runId/status", () => {
  let app: ReturnType<typeof buildApp>;
  let runId: string;

  beforeEach(async () => {
    await resetStore();
    app = buildApp();
    const response = await app.inject({ method: "POST", url: "/api/simulation/runs", payload: {} });
    runId = response.json().runId;
  });
