import type { FastifyInstance } from "fastify";
import { v4 as uuidv4 } from "uuid";
import type { SimulationRun } from "@/domain/types";
import { RunStatus, StockUpdateMode, EventType } from "@/domain/types";
import { appendEvent } from "@/engine/event-log";
import { store } from "@/store/redis.store";

/**
 * Registers simulation run management routes.
 * @param app - Fastify application instance.
 */
export async function simulationRoutes(app: FastifyInstance): Promise<void> {
  app.post<{ Body: Partial<Pick<SimulationRun, "consumptionSignalId" | "signalLoop" | "stockUpdateMode">> }>(
    "/api/simulation/runs",
    async (request, reply) => {
      const run: SimulationRun = {
        consumptionSignalId: request.body.consumptionSignalId,
        runId: uuidv4(),
        signalLoop: request.body.signalLoop ?? false,
        status: RunStatus.IDLE,
        stockUpdateMode: request.body.stockUpdateMode ?? StockUpdateMode.PerCycle,
      };
      await store.setRun(run.runId, run);

      // Initialise stock for all known references
      const references = await store.getAllReferences();
      await Promise.all(
        references.map(async (reference) => {
          const key = store.stockKey(run.runId, reference.material);
          await store.setStock(key, {
            currentStock: reference.initialStock,
            lastUpdatedAt: new Date().toISOString(),
            material: reference.material,
            runId: run.runId,
          });
        }),
      );

      return reply.code(201).send(run);
    },
  );

  app.post<{ Params: { runId: string } }>("/api/simulation/runs/:runId/start", async (request, reply) => {
    const run = await store.getRun(request.params.runId);
    if (!run) return reply.code(404).send({ error: "NOT_FOUND" });
    if (run.status === RunStatus.RUNNING) return reply.code(409).send({ error: "ALREADY_RUNNING" });

    const updated = { ...run, startedAt: run.startedAt ?? new Date().toISOString(), status: RunStatus.RUNNING };
    await store.setRun(updated.runId, updated);
    await appendEvent({ runId: updated.runId, type: EventType.RUN_STARTED });
    return updated;
  });

  app.post<{ Params: { runId: string } }>("/api/simulation/runs/:runId/pause", async (request, reply) => {
    const run = await store.getRun(request.params.runId);
    if (!run) return reply.code(404).send({ error: "NOT_FOUND" });
    const updated = { ...run, status: RunStatus.PAUSED };
    await store.setRun(updated.runId, updated);
    await appendEvent({ runId: updated.runId, type: EventType.RUN_PAUSED });
    return updated;
  });

  app.post<{ Params: { runId: string } }>("/api/simulation/runs/:runId/reset", async (request, reply) => {
    const run = await store.getRun(request.params.runId);
    if (!run) return reply.code(404).send({ error: "NOT_FOUND" });

    const updated = { ...run, startedAt: undefined, status: RunStatus.IDLE };
    await store.setRun(updated.runId, updated);

    // Clear work requests for this run
    const allWrs = await store.getAllWorkRequests();
    await Promise.all(allWrs.filter(wr => wr.runId === run.runId).map(async wr => store.deleteWorkRequest(wr.id)));

    // Reset stock to initial levels
    const references = await store.getAllReferences();
    await Promise.all(
      references.map(async (reference) => {
        const key = store.stockKey(run.runId, reference.material);
        await store.setStock(key, {
          currentStock: reference.initialStock,
          lastUpdatedAt: new Date().toISOString(),
          material: reference.material,
          runId: run.runId,
        });
      }),
    );

    await appendEvent({ runId: run.runId, type: EventType.RUN_RESET });
    return updated;
  });

  app.get<{ Params: { runId: string } }>("/api/simulation/runs/:runId/status", async (request, reply) => {
    const run = await store.getRun(request.params.runId);
    if (!run) return reply.code(404).send({ error: "NOT_FOUND" });
    return run;
  });
}

