import type { FastifyInstance } from "fastify";
import { store } from "@/store/redis.store";

/**
 * Registers stock query routes.
 * @param app - Fastify application instance.
 */
export async function stockRoutes(app: FastifyInstance): Promise<void> {
  app.get("/api/stock", async () => {
    const stocks = await store.getAllStocks();
    return Promise.all(
      stocks.map(async (s) => {
        const reference = await store.getReference(s.material);
        return {
          currentStock: s.currentStock,
          description: reference?.description ?? "",
          lastUpdatedAt: s.lastUpdatedAt,
          material: s.material,
          stockMax: reference?.stockMax ?? 0,
          stockMin: reference?.stockMin ?? 0,
          unit: reference?.unit ?? "pcs",
        };
      }),
    );
  });

  app.get<{ Params: { material: string } }>("/api/stock/:material", async (request, reply) => {
    const all = await store.getAllStocks();
    const stock = all.find(item => item.material === request.params.material);
    if (!stock)
      return reply.code(404).send({
        error: "NOT_FOUND",
        message: `Material ${request.params.material} not found in active run`,
      });
    const reference = await store.getReference(stock.material);
    return {
      currentStock: stock.currentStock,
      description: reference?.description ?? "",
      lastUpdatedAt: stock.lastUpdatedAt,
      material: stock.material,
      stockMax: reference?.stockMax ?? 0,
      stockMin: reference?.stockMin ?? 0,
      unit: reference?.unit ?? "pcs",
    };
  });
}

