import type { FastifyInstance } from "fastify";
import { v4 as uuidv4 } from "uuid";
import type { SimWorkRequest } from "@/domain/types";
import { RequestState, EventType } from "@/domain/types";
import { appendEvent } from "@/engine/event-log";
import { store } from "@/store/redis.store";

interface CreateBody {
  endTime: string
  orderedQuantity: number
  priority?: number
  runId?: string
  scheduledEquipmentId: string
  schedulerOrderId: string
  startTime: string
  workMasterId: string
  workMasterVersion: string
}

interface UpdateBody {
  endTime?: string
  orderedQuantity?: number
  priority?: number
  startTime?: string
}

/**
 * Computes the target release time from a start time and lead time.
 * @param startTime - ISO 8601 start time of the work request.
 * @param leadTimeSeconds - Lead time in seconds to subtract from startTime.
 * @returns The computed target release ISO 8601 timestamp.
 */
function computeTargetReleaseAt(startTime: string, leadTimeSeconds: number): string {
  return new Date(new Date(startTime).getTime() - leadTimeSeconds * 1000).toISOString();
}

/**
 * Registers work request CRUD routes.
 * @param app - Fastify application instance.
 */
export async function workRequestRoutes(app: FastifyInstance): Promise<void> {
  app.post<{ Body: CreateBody }>("/api/work-requests", async (request, reply) => {
    const { schedulerOrderId, workMasterId, workMasterVersion, scheduledEquipmentId, orderedQuantity, startTime, endTime, priority, runId } = request.body;

    if (!schedulerOrderId || !workMasterId || !workMasterVersion || !scheduledEquipmentId || orderedQuantity === undefined || !startTime || !endTime) {
      return reply.code(400).send({
        error: "MISSING_FIELDS",
        message: "schedulerOrderId, workMasterId, workMasterVersion, scheduledEquipmentId, orderedQuantity, startTime, endTime are required",
      });
    }
    if (orderedQuantity <= 0)
      return reply.code(400).send({ error: "INVALID_QUANTITY", message: "orderedQuantity must be > 0" });
    if (new Date(endTime) <= new Date(startTime))
      return reply.code(400).send({ error: "INVALID_TIME_RANGE", message: "endTime must be after startTime" });

    const machine = await store.getMachine(scheduledEquipmentId);

    const allWrs = await store.getAllWorkRequests();
    const duplicate = allWrs.find(w => w.schedulerOrderId === schedulerOrderId && w.runId === (runId ?? ""));
    if (duplicate)
      return reply.code(400).send({ error: "DUPLICATE_ID", message: `schedulerOrderId ${schedulerOrderId} already exists in this run` });

    const now = new Date().toISOString();
    const wr: SimWorkRequest = {
      createdAt: now,
      endTime,
      id: uuidv4(),
      orderedQuantity,
      priority: priority ?? new Date(startTime).getTime(),
      remainingQuantity: orderedQuantity,
      requestState: RequestState.Forecast,
      runId: runId ?? "",
      scheduledEquipmentId,
      schedulerOrderId,
      startTime,
      targetReleaseAt: computeTargetReleaseAt(startTime, machine?.leadTimeBeforeBottleneck ?? 0),
      workMasterId,
      workMasterVersion,
    };

    await store.setWorkRequest(wr.id, wr);
    await appendEvent({
      orderId: wr.id,
      runId: wr.runId,
      scheduledEquipmentId,
      type: EventType.WORK_REQUEST_CREATED,
    });
    return reply.code(201).send(wr);
  });

  app.get<{ Querystring: { material?: string, requestState?: string, runId?: string, scheduledEquipmentId?: string } }>(
    "/api/work-requests",
    async (request) => {
      let results = await store.getAllWorkRequests();
      const { scheduledEquipmentId, material, requestState, runId } = request.query;
      if (scheduledEquipmentId !== undefined) results = results.filter(w => w.scheduledEquipmentId === scheduledEquipmentId);
      if (material !== undefined) results = results.filter(w => w.material === material);
      if (requestState !== undefined) results = results.filter(w => (w.requestState as string) === requestState);
      if (runId !== undefined) results = results.filter(w => w.runId === runId);
      return results;
    },
  );

  app.get<{ Params: { id: string } }>("/api/work-requests/:id", async (request, reply) => {
    const wr = await store.getWorkRequest(request.params.id);
    if (!wr) return reply.code(404).send({ error: "NOT_FOUND", message: `WorkRequest ${request.params.id} not found` });
    return wr;
  });

  app.patch<{ Body: UpdateBody, Params: { id: string } }>("/api/work-requests/:id", async (request, reply) => {
    const wr = await store.getWorkRequest(request.params.id);
    if (!wr) return reply.code(404).send({ error: "NOT_FOUND", message: `WorkRequest ${request.params.id} not found` });
    const isTerminal = wr.requestState === RequestState.Completed || wr.requestState === RequestState.Cancelled;
    if (isTerminal) {
      return reply.code(409).send({
        error: "TERMINAL_STATE",
        message: `WorkRequest ${request.params.id} is ${wr.requestState} and cannot be modified`,
      });
    }

    const isForecast = wr.requestState === RequestState.Forecast;
    const { orderedQuantity, startTime, endTime, priority } = request.body;

    // OrderedQuantity and priority are only editable in Forecast state
    if ((orderedQuantity !== undefined || priority !== undefined) && !isForecast) {
      return reply.code(409).send({
        error: "ALREADY_RELEASED",
        message: `WorkRequest ${request.params.id} is ${wr.requestState}: only startTime and endTime can be updated`,
      });
    }

    let updated = { ...wr };
    if (orderedQuantity !== undefined) {
      updated = { ...updated, orderedQuantity, remainingQuantity: orderedQuantity };
    }
    if (startTime !== undefined) {
      updated = { ...updated, startTime };
      if (isForecast) {
        const newPriority = new Date(startTime).getTime();
        const machine = await store.getMachine(updated.scheduledEquipmentId);
        updated = {
          ...updated,
          priority: newPriority,
          targetReleaseAt: machine
            ? computeTargetReleaseAt(startTime, machine.leadTimeBeforeBottleneck)
            : updated.targetReleaseAt,
        };
      }
    }
    if (endTime !== undefined) updated = { ...updated, endTime };
    if (priority !== undefined) updated = { ...updated, priority };

    await store.setWorkRequest(updated.id, updated);
    await appendEvent({ orderId: updated.id, runId: updated.runId, type: EventType.WORK_REQUEST_UPDATED });
    return updated;
  });

  app.delete<{ Params: { id: string } }>("/api/work-requests/:id", async (request, reply) => {
    const wr = await store.getWorkRequest(request.params.id);
    if (!wr) return reply.code(404).send({ error: "NOT_FOUND", message: `WorkRequest ${request.params.id} not found` });

    if (wr.requestState === RequestState.Released || wr.requestState === RequestState.Running) {
      return reply.code(409).send({
        error: "ALREADY_RELEASED",
        message: `WorkRequest ${request.params.id} is ${wr.requestState} and cannot be cancelled — unrelease it first`,
      });
    }
    if (wr.requestState === RequestState.Completed || wr.requestState === RequestState.Cancelled) {
      return reply.code(409).send({
        error: "TERMINAL_STATE",
        message: `WorkRequest ${request.params.id} is already in terminal state ${wr.requestState}`,
      });
    }

    const cancelled = { ...wr, completedAt: new Date().toISOString(), requestState: RequestState.Cancelled };
    await store.setWorkRequest(cancelled.id, cancelled);
    await appendEvent({ orderId: cancelled.id, runId: cancelled.runId, type: EventType.WORK_REQUEST_CANCELLED });
    return cancelled;
  });
}

import cors from "@fastify/cors";
import fastify from "fastify";
import { Server as SocketIOServer } from "socket.io";
import { environment } from "./config/environment";
import { startEngine } from "@/engine/simulation-engine";
import { configRoutes } from "@/routes/config.route";
import { eventRoutes } from "@/routes/events.route";
import { healthRoutes } from "@/routes/health.route";
import { inventoryRoutes } from "@/routes/inventory.route";
import { signalRoutes } from "@/routes/signals.route";
import { simulationRoutes } from "@/routes/simulation.route";
import { stockRoutes } from "@/routes/stock.route";
import { workRequestRoutes } from "@/routes/work-requests.route";
import { store } from "@/store/redis.store";

/**
 *
 */
async function bootstrap(): Promise<void> {
  await store.connect();

  const app = fastify({ logger: { level: environment.nodeEnv === "production" ? "info" : "debug" } });

  await app.register(cors, { methods: ["DELETE", "GET", "OPTIONS", "PATCH", "POST"], origin: "*" });

  await app.register(healthRoutes);
  await app.register(stockRoutes);
  await app.register(workRequestRoutes);
  await app.register(simulationRoutes);
  await app.register(signalRoutes);
  await app.register(eventRoutes);
  await app.register(inventoryRoutes);
  await app.register(configRoutes);

  const address = await app.listen({ host: "0.0.0.0", port: environment.port });
  app.log.info(`chronos-be listening at ${address}`);
  startEngine();

  const io = new SocketIOServer(app.server, { cors: { origin: "*" } });
  io.on("connection", (socket) => {
    app.log.debug(`socket connected: ${socket.id}`);
    socket.on("subscribe:run", (runId: string) => socket.join(`run:${runId}`));
    socket.on("unsubscribe:run", (runId: string) => socket.leave(`run:${runId}`));
  });

  // Graceful shutdown
  const shutdown = async (signal: string): Promise<void> => {
    app.log.info(`Received ${signal}, shutting down`);
    await io.close();
    await app.close();
    await store.disconnect();
    process.exitCode = 0;
  };

  process.on("SIGTERM", () => {
    shutdown("SIGTERM").catch(() => { /* Intentionally swallow shutdown errors */ });
  });
  process.on("SIGINT", () => {
    shutdown("SIGINT").catch(() => { /* Intentionally swallow shutdown errors */ });
  });
}

bootstrap().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

