import { JobsLoggerService, RedisConnectionService, redisConnectionFactory } from "@mesx/common-lib";
import { environment } from "@/config/environment";

let connection: RedisConnectionService | undefined;

/**
 * Returns a singleton Redis connection, creating it if needed.
 * @returns The active RedisConnectionService instance.
 */
export async function getRedisConnection(): Promise<RedisConnectionService> {
  if (connection) return connection;

  const logger = new JobsLoggerService(environment.nodeEnv === "production" ? "log" : "debug");

  connection = await redisConnectionFactory(
    {
      localRedisPassword: environment.redis.password,
      redisHostManagedRedis: environment.redis.host,
      useRedisLocal: environment.redis.useLocal,
      useTls: environment.redis.useTls,
      username: environment.redis.username,
    },
    logger,
  );

  return connection;
}

/**
 * Closes the singleton Redis connection.
 */
export async function closeRedisConnection(): Promise<void> {
  await connection?.disconnect();
  connection = undefined;
}

import type { RedisClientInstance } from "@mesx/common-lib";
import { InMemoryStore } from "./in-memory.store.js";
import { closeRedisConnection, getRedisConnection } from "./redis.client.js";
import { environment } from "@/config/environment";
import type {
  ConsumptionSignal,
  ConsumptionSignalEvent,
  Machine,
  MachineCapability,
  Reference,
  SimConfig,
  SimEvent,
  SimStock,
  SimulationRun,
  SimWorkRequest,
} from "@/domain/types";

const P = environment.redis.statePrefix;

const keys = {
  capabilities: (id: string) => `${P}:caps:${id}`,
  config: `${P}:config`,
  events: `${P}:events`,
  machine: (id: string) => `${P}:machine:${id}`,
  machines: `${P}:machine-ids`,
  reference: (id: string) => `${P}:ref:${id}`,
  references: `${P}:ref-ids`,
  run: (id: string) => `${P}:run:${id}`,
  runs: `${P}:run-ids`,
  signal: (id: string) => `${P}:signal:${id}`,
  signalEvents: (id: string) => `${P}:signal-events:${id}`,
  signals: `${P}:signal-ids`,
  stock: (key: string) => `${P}:stock:${key}`,
  stocks: `${P}:stock-keys`,
  workRequest: (id: string) => `${P}:wr:${id}`,
  workRequests: `${P}:wr-ids`,
} as const;

/**
 * Returns the active Redis client instance.
 * @returns The Redis client from the current connection.
 */
async function getClient(): Promise<RedisClientInstance> {
  const conn = await getRedisConnection();
  return conn.getClient();
}

/**
 * Parses an array of raw Redis strings into typed objects, filtering out nulls.
 * @param raws - Raw JSON strings (or nulls) from Redis.
 * @returns Array of parsed typed values with nulls removed.
 */
function parseRaws<T>(raws: Array<string | null>): Array<T> {
  return raws
    .filter((r): r is string => r !== null)
    .map(r => JSON.parse(r) as T);
}

/**
 * Parses a nullable raw Redis string into a typed value or undefined.
 * @param raw - Raw JSON string from Redis, or null if the key was absent.
 * @returns The parsed typed value, or undefined if raw is null.
 */
function parseOptional<T>(raw: string | null): T | undefined {
  return raw === null ? undefined : (JSON.parse(raw) as T);
}

/**
 * Parses a nullable raw Redis string into a typed value, returning a fallback if null.
 * @param raw - Raw JSON string from Redis, or null if the key was absent.
 * @param fallback - Default value returned when raw is null.
 * @returns The parsed typed value, or the fallback if raw is null.
 */
function parseWithDefault<T>(raw: string | null, fallback: T): T {
  return raw === null ? fallback : (JSON.parse(raw) as T);
}

export class RedisStore {
  public stockKey(runId: string, material: string): string {
    return `${runId}::${material}`;
  }

  public async connect(): Promise<void> {
    await getRedisConnection();
  }

  public async disconnect(): Promise<void> {
    await closeRedisConnection();
  }

  // ── Runs ─────────────────────────────────────────────────────────────────

  public async getRun(runId: string): Promise<SimulationRun | undefined> {
    const c = await getClient();
    const raw = await c.get(keys.run(runId));
    return parseOptional<SimulationRun>(raw);
  }

  public async setRun(runId: string, run: SimulationRun): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.set(keys.run(runId), JSON.stringify(run));
    multi.sAdd(keys.runs, runId);
    await multi.exec();
  }

  public async getAllRuns(): Promise<Array<SimulationRun>> {
    const c = await getClient();
    const ids = await c.sMembers(keys.runs);
    if (ids.length === 0) return [];
    const raws = await Promise.all(ids.map(id => c.get(keys.run(id))));
    return parseRaws<SimulationRun>(raws);
  }

  // ── Stocks ────────────────────────────────────────────────────────────────

  public async getStock(key: string): Promise<SimStock | undefined> {
    const c = await getClient();
    const raw = await c.get(keys.stock(key));
    return parseOptional<SimStock>(raw);
  }

  public async setStock(key: string, stock: SimStock): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.set(keys.stock(key), JSON.stringify(stock));
    multi.sAdd(keys.stocks, key);
    await multi.exec();
  }

  public async getAllStocks(): Promise<Array<SimStock>> {
    const c = await getClient();
    const ks = await c.sMembers(keys.stocks);
    if (ks.length === 0) return [];
    const raws = await Promise.all(ks.map(k => c.get(keys.stock(k))));
    return parseRaws<SimStock>(raws);
  }

  // ── Work Requests ─────────────────────────────────────────────────────────

  public async getWorkRequest(id: string): Promise<SimWorkRequest | undefined> {
    const c = await getClient();
    const raw = await c.get(keys.workRequest(id));
    return parseOptional<SimWorkRequest>(raw);
  }

  public async setWorkRequest(id: string, wr: SimWorkRequest): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.set(keys.workRequest(id), JSON.stringify(wr));
    multi.sAdd(keys.workRequests, id);
    await multi.exec();
  }

  public async deleteWorkRequest(id: string): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.del(keys.workRequest(id));
    multi.sRem(keys.workRequests, id);
    await multi.exec();
  }

  public async hasWorkRequest(id: string): Promise<boolean> {
    const c = await getClient();
    return (await c.exists(keys.workRequest(id))) === 1;
  }

  public async getAllWorkRequests(): Promise<Array<SimWorkRequest>> {
    const c = await getClient();
    const ids = await c.sMembers(keys.workRequests);
    if (ids.length === 0) return [];
    const raws = await Promise.all(ids.map(id => c.get(keys.workRequest(id))));
    return parseRaws<SimWorkRequest>(raws);
  }

  // ── Events ────────────────────────────────────────────────────────────────

  public async appendEvent(event: SimEvent): Promise<void> {
    const c = await getClient();
    await c.rPush(keys.events, JSON.stringify(event));
  }

  public async getEvents(): Promise<Array<SimEvent>> {
    const c = await getClient();
    const raws = await c.lRange(keys.events, 0, -1);
    return raws.map(r => JSON.parse(r) as SimEvent);
  }

  // ── Signals ───────────────────────────────────────────────────────────────

  public async getSignal(signalId: string): Promise<ConsumptionSignal | undefined> {
    const c = await getClient();
    const raw = await c.get(keys.signal(signalId));
    return parseOptional<ConsumptionSignal>(raw);
  }

  public async setSignal(signalId: string, signal: ConsumptionSignal): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.set(keys.signal(signalId), JSON.stringify(signal));
    multi.sAdd(keys.signals, signalId);
    await multi.exec();
  }

  public async getAllSignals(): Promise<Array<ConsumptionSignal>> {
    const c = await getClient();
    const ids = await c.sMembers(keys.signals);
    if (ids.length === 0) return [];
    const raws = await Promise.all(ids.map(id => c.get(keys.signal(id))));
    return parseRaws<ConsumptionSignal>(raws);
  }

  public async getSignalEvents(signalId: string): Promise<Array<ConsumptionSignalEvent>> {
    const c = await getClient();
    const raw = await c.get(keys.signalEvents(signalId));
    return parseWithDefault<Array<ConsumptionSignalEvent>>(raw, []);
  }

  public async setSignalEvents(signalId: string, events: Array<ConsumptionSignalEvent>): Promise<void> {
    const c = await getClient();
    await c.set(keys.signalEvents(signalId), JSON.stringify(events));
  }

  // ── Machines ──────────────────────────────────────────────────────────────

  public async getMachine(id: string): Promise<Machine | undefined> {
    const c = await getClient();
    const raw = await c.get(keys.machine(id));
    return parseOptional<Machine>(raw);
  }

  public async setMachine(id: string, machine: Machine): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.set(keys.machine(id), JSON.stringify(machine));
    multi.sAdd(keys.machines, id);
    await multi.exec();
  }

  // ── References ────────────────────────────────────────────────────────────

  public async getReference(material: string): Promise<Reference | undefined> {
    const c = await getClient();
    const raw = await c.get(keys.reference(material));
    return parseOptional<Reference>(raw);
  }

  public async setReference(material: string, reference: Reference): Promise<void> {
    const c = await getClient();
    const multi = c.multi();
    multi.set(keys.reference(material), JSON.stringify(reference));
    multi.sAdd(keys.references, material);
    await multi.exec();
  }

  public async getAllReferences(): Promise<Array<Reference>> {
    const c = await getClient();
    const ids = await c.sMembers(keys.references);
    if (ids.length === 0) return [];
    const raws = await Promise.all(ids.map(id => c.get(keys.reference(id))));
    return parseRaws<Reference>(raws);
  }

  // ── Config ────────────────────────────────────────────────────────────────

  public async getConfig(): Promise<SimConfig> {
    const c = await getClient();
    const raw = await c.get(keys.config);
    return parseWithDefault<SimConfig>(raw, { leadTimeSeconds: 3600 });
  }

  public async setConfig(config: SimConfig): Promise<void> {
    const c = await getClient();
    await c.set(keys.config, JSON.stringify(config));
  }

  // ── Capabilities ──────────────────────────────────────────────────────────

  public async getCapabilities(equipmentId: string): Promise<Array<MachineCapability>> {
    const c = await getClient();
    const raw = await c.get(keys.capabilities(equipmentId));
    return parseWithDefault<Array<MachineCapability>>(raw, []);
  }

  public async setCapabilities(equipmentId: string, caps: Array<MachineCapability>): Promise<void> {
    const c = await getClient();
    await c.set(keys.capabilities(equipmentId), JSON.stringify(caps));
  }
}

