import fastify from "fastify";
import type { RequestState } from "@/domain/types";
import { healthRoutes } from "@/routes/health.route";
import { simulationRoutes } from "@/routes/simulation.route";
import { stockRoutes } from "@/routes/stock.route";
import { workRequestRoutes } from "@/routes/work-requests.route";
import { store } from "@/store/redis.store";

/**
 * Builds a Fastify app instance for testing.
 * @returns A configured Fastify instance with all test routes registered.
 */
export function buildApp(): ReturnType<typeof fastify> {
  const app = fastify({ logger: false });
  void app.register(healthRoutes);
  void app.register(stockRoutes);
  void app.register(workRequestRoutes);
  void app.register(simulationRoutes);
  return app;
}

/**
 * Connects the Redis store.
 */
export async function connectStore(): Promise<void> {
  await store.connect();
}

/**
 * Resets all store state between tests.
 * @returns A resolved promise.
 */
export function resetStore(): Promise<void> {
  if ("reset" in store && typeof (store as { reset: () => void }).reset === "function") {
    (store as { reset: () => void }).reset();
  }
  return Promise.resolve();
}

/**
 * Seeds a test machine with optional overrides.
 * @param overrides - Partial machine fields to override the defaults.
 * @returns The seeded machine object.
 */
export async function seedMachine(
  overrides: Partial<{ equipmentId: string, leadTimeBeforeBottleneck: number }> = {},
): Promise<{
  cycleTimeJitterPct: number
  cycleTimeSeconds: number
  equipmentId: string
  leadTimeBeforeBottleneck: number
  name: string
}> {
  const machine = {
    cycleTimeJitterPct: 0,
    cycleTimeSeconds: 10,
    equipmentId: "WC001",
    leadTimeBeforeBottleneck: 600,
    name: "Test Machine",
    ...overrides,
  };
  await store.setMachine(machine.equipmentId, machine);
  await store.setCapabilities(machine.equipmentId, [{ material: "MAT-A", scheduledEquipmentId: machine.equipmentId }]);
  return machine;
}

/**
 * Seeds stock and a reference for testing.
 * @param runId - ID of the simulation run.
 * @param material - Material identifier to seed stock for.
 * @param currentStock - Initial stock level to seed.
 */
export async function seedStock(runId: string, material: string, currentStock: number): Promise<void> {
  const reference = {
    description: `${material} description`,
    initialStock: currentStock,
    material,
    piecesPerCycle: 1,
    stockMax: 500,
    stockMin: 10,
    unit: "pcs",
  };
  await store.setReference(material, reference);
  await store.setStock(store.stockKey(runId, material), {
    currentStock,
    lastUpdatedAt: new Date().toISOString(),
    material,
    runId,
  });
}

/**
 * Patches a work request's state directly in the store for test setup.
 * @param id - UUID of the work request to patch.
 * @param requestState - Target request state to set on the work request.
 */
export async function patchWorkRequestState(id: string, requestState: RequestState): Promise<void> {
  const wr = await store.getWorkRequest(id);
  if (!wr) throw new Error(`WorkRequest ${id} not found`);
  await store.setWorkRequest(id, { ...wr, requestState });
}

